solution.solution.cpp:
class IdleTracker
{
public:
    explicit IdleTracker(int settleFrames) : m_settle{ settleFrames }, m_left{ settleFrames } {}
    void onInput() { m_left = m_settle; }
    void setAnimating(bool animating) { m_animating = animating; }
    bool shouldDraw()
    {
        if (m_animating) return true;
        if (m_left > 0) { --m_left; return true; }
        return false;
    }
private:
    int m_settle;
    int m_left;
    bool m_animating{ false };
};

unitTests:
TEST("draws at start, then sleeps") { IdleTracker t{ 2 }; CHECK(t.shouldDraw()); CHECK(t.shouldDraw()); CHECK(!t.shouldDraw()); CHECK(!t.shouldDraw()); }
TEST("input wakes it") { IdleTracker t{ 3 }; for (int i = 0; i < 5; ++i) t.shouldDraw(); t.onInput(); CHECK(t.shouldDraw()); CHECK(t.shouldDraw()); CHECK(t.shouldDraw()); CHECK(!t.shouldDraw()); }
TEST("input restarts the count") { IdleTracker t{ 2 }; t.shouldDraw(); t.onInput(); t.shouldDraw(); t.onInput(); CHECK(t.shouldDraw()); CHECK(t.shouldDraw()); CHECK(!t.shouldDraw()); }
TEST("animating always draws") { IdleTracker t{ 1 }; t.shouldDraw(); t.setAnimating(true); for (int i = 0; i < 10; ++i) CHECK(t.shouldDraw()); t.setAnimating(false); CHECK(!t.shouldDraw()); }

